-- ══════════════════════════════════════════════════════════════════════════════════════════════════════════
-- OPS LEDGER: which SQL files has production applied, when, and at which content?  (2026-10-28, cleanup 0.3)
-- ══════════════════════════════════════════════════════════════════════════════════════════════════════════
--
-- Apply with `npm run db:apply -- supabase/migrations/2026-11-07-ops-schema-ledger.sql --yes` (the wrapper records
-- this file in the ledger it creates). Idempotent: safe to re-run. Additive only: rollback = `drop schema ops cascade`.
-- No Edge Function needs redeploying. Scope: docs/design/2026-10-28-supabase-cleanup.md section 5.2.
--
-- WHY (owner 2026-10-28: "scope out a massive supabase clean up so that we're running really cleanly across the
-- board"): nothing recorded which of supabase/migrations/*.sql had been applied, when, or in what order, so "is it
-- applied?" could only be answered by diffing function bodies (scripts/supabase/drift.mjs), and apply order already
-- differs from filename order in three places. From now on every apply goes through `npm run db:apply`, which runs
-- the file and appends one row here; `npm run db:ledger` lists PENDING / CHANGED files.
--
--  - `ops` is a private schema: no client role can see it (PostgREST exposes only `public`, and usage is revoked).
--  - `ops.schema_ledger` is append-only history: one row per apply (a re-apply after an edit is a second row).
--  - The SEED backfills one row per file that was live on 2026-10-28, `applied_by = 'pre-ledger'`, with the evidence
--    from the drift check in `note` (generated by `npm run db:ledger -- --seed-sql`). NOT seeded, because it was never
--    applied: 2026-10-08-god-board-sample.sql (`god_board_sample` does not exist in production).

begin;

create schema if not exists ops;
revoke all on schema ops from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on schema ops from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on schema ops from authenticated'; end if;
end $$;

create table if not exists ops.schema_ledger (
  id         bigserial primary key,
  file       text not null,                       -- repo-relative, forward slashes: supabase/migrations/<name>.sql
  sha256     text not null,                       -- of the file with CRLF normalized to LF (scripts/supabase/lib.mjs)
  applied_at timestamptz not null default now(),
  applied_by text not null default current_user,  -- the wrapper passes the git user; 'pre-ledger' for the seed
  commit_sha text,                                -- HEAD of the checkout the file was applied from
  note       text
);
create index if not exists schema_ledger_file on ops.schema_ledger (file, id desc);
revoke all on ops.schema_ledger from public;

insert into ops.schema_ledger (file, sha256, applied_at, applied_by, note)
